{"results": [{"id": "hp_doc_c9e6e6279cc9205e039017f4d5921e1ebcd7397521231866a7c240700a044623", "title": "1997 Porsche Tennis Grand Prix", "text": "The 1997 Porsche Tennis Grand Prix was a women's tennis tournament played on indoor hard courts at the Filderstadt Tennis Club in Filderstadt in Germany that was part of Tier II of the 1997 WTA Tour. It was the 20th edition of the tournament and was held from 6 October through 12 October 1997. First-seeded Martina Hingis won the singles title, her second consecutive at the event.", "score": 45.0945}, {"id": "hp_doc_0e5f6f20564798cf19bc897d292c4ac6b3218f12b5786cd0845d1f800b8133de", "title": "2015 Porsche Tennis Grand Prix", "text": "The 2015 Porsche Tennis Grand Prix was a women's tennis tournament played on indoor clay courts. It was the 38th edition of the Porsche Tennis Grand Prix, and part of the Premier tournaments of the 2015 WTA Tour. It took place at the Porsche Arena in Stuttgart, Germany, from 20 April through 26 April 2015. Unseeded Angelique Kerber won the singles title.", "score": 42.9687}, {"id": "hp_doc_54c82e527072f138442277c02083fe71bec17da68a7b73ea62ec44f4d191295f", "title": "2013 Porsche Tennis Grand Prix", "text": "The 2013 Porsche Tennis Grand Prix was a tennis tournament played on indoor clay courts. It was the 36th edition of the Porsche Tennis Grand Prix, and was part of the Premier tournaments of the 2013 WTA Tour. It took place at the Porsche Arena in Stuttgart, Germany, from April 22 through 28, 2013.", "score": 39.4154}], "remaining_searches": 2}
